/**
 * 依學生+科目彙總各狀態筆數（忽略 reviewTab，只保留科目篩選）。
 * 用於在子分組旁顯示「目前 tab 以外還有哪些狀態」的 chips，避免使用者以為資料遺失。
 * 參考：GitHub PR tabs / Linear / Gmail 標籤的 faceted counts 模式。
 */
const subjectStatusCounts = computed(() => {
  const subjectFilter = String(filters.subject || '').trim();
  const map = new Map();
  for (const record of records.value || []) {
    if (subjectFilter && recordSubjectKey(record) !== subjectFilter) continue;
    const studentId = Number(record?.student_id || 0) || null;
    const studentName = String(record?.student_name || '').trim() || '未命名學生';
    const studentKey = studentId ? `student-${studentId}` : `name-${studentName}`;
    const subjKey = recordSubjectKey(record);
    const compositeKey = `${studentKey}::${subjKey}`;
    if (!map.has(compositeKey)) {
      map.set(compositeKey, {
        approved: 0,
        pending: 0,
        changes_requested: 0,
        rejected: 0,
        unfilled: 0,
        total: 0,
      });
    }
    const c = map.get(compositeKey);
    c.total += 1;
    const s = record?.Status;
    if (s === 'approved') c.approved += 1;
    else if (s === 'rejected') c.rejected += 1;
    else if (s === 'changes_requested') c.changes_requested += 1;
    else if (s === 'pending') c.pending += 1;
    if ((s === 'pending' || s === 'changes_requested') && !hasLearningRecordBody(record)) c.unfilled += 1;
  }
  return map;
});

/**
 * 取得某學生某科目的狀態分佈，用於在子分組 header 顯示 chips。
 * 回傳結構：{ approved, pending, changes_requested, rejected, unfilled, total }
 */
const getSubjectStatusCounts = (groupKey, subject) => {
  return subjectStatusCounts.value.get(`${groupKey}::${subject}`) || null;
};

/**
 * 目前頂部 tab（reviewTab / teacherFilterTab）隱藏了幾筆「否則會顯示」的記錄。

/**
 * 某學生某科目被目前 tab 隱藏的筆數（total - 落在 tab 內的筆數）。
 */
const subjectHiddenCount = (groupKey, subject) => {
  const c = getSubjectStatusCounts(groupKey, subject);
  if (!c) return 0;
  let shown = 0;
  if (isStatusInCurrentTab('approved')) shown += c.approved;
  if (isStatusInCurrentTab('pending')) shown += c.pending;
  if (isStatusInCurrentTab('changes_requested')) shown += c.changes_requested;
  if (isStatusInCurrentTab('rejected')) shown += c.rejected;
  return Math.max(0, c.total - shown);
};

