// Keyset (cursor) pagination branch: when `before_id` is supplied the caller is walking the
// dataset chronologically backwards using a stable anchor (the smallest `id` seen so far).
// This avoids the OFFSET "sliding window" problem when rows are inserted between calls
// (see Slack Engineering: "Evolving API Pagination at Slack"). When this branch is taken
// the `page` parameter is completely ignored — the two pagination modes never share state.
if ($request->filled('before_id')) {
    $beforeId = (int) $request->input('before_id');
    if ($beforeId > 0) {
        $query->where('id', '<', $beforeId);
    }

    // Terminate-on-empty: callers MUST stop when `data` is empty. We still report a
    // hint `has_more` based on whether we filled the page, matching Slack's next_cursor idiom.
    $rows = $query->with('studentClass.student')
        ->orderBy('SessionDate', 'desc')
        ->orderBy('id', 'desc')
        ->limit($perPage)
        ->get();

