cd /home/admin/backend && php artisan tinker --execute="
\$courses = \App\Models\StudentClass::whereNotNull('PackageID')->get();
\$fixed = 0;
foreach (\$courses as \$sc) {
  \$pkg = \App\Models\CoursePackage::find(\$sc->PackageID);
  if (!\$pkg || \$pkg->total_sessions <= 0) continue;
  \$memberCount = \App\Models\StudentClass::where('PackageID', \$sc->PackageID)->count();
  if (\$memberCount <= 0) continue;
  \$expected = (int) floor(\$pkg->total_sessions / \$memberCount);
  if ((int)\$sc->SessionCount === (int)\$pkg->total_sessions && \$memberCount > 1) {
    echo 'FIX SC=' . \$sc->ID . ' SessionCount ' . \$sc->SessionCount . ' -> ' . \$expected . ' (pkg=' . \$pkg->total_sessions . ', members=' . \$memberCount . ')' . PHP_EOL;
    \$sc->update(['SessionCount' => \$expected]);
    \$fixed++;
  }
}
echo 'Total fixed: ' . \$fixed . PHP_EOL;
" 2>&1

